// Prepare all 9 register reads in parallel
const reads = [
    { name: 'runState', address: 600, quantity: 1 },
    { name: 'commBoard', address: 648, quantity: 1 },
    { name: 'warning1', address: 653, quantity: 1 },
    { name: 'warning2', address: 654, quantity: 1 },
    { name: 'fault1', address: 655, quantity: 1 },
    { name: 'fault2', address: 656, quantity: 1 },
    { name: 'fault3', address: 657, quantity: 1 },
    { name: 'fault4', address: 658, quantity: 1 },
    { name: 'workFlag', address: 659, quantity: 1 }
];

const messages = reads.map(r => ({
    payload: {
        fc: 3,
        unitid: 1,
        address: r.address,
        quantity: r.quantity
    },
    readName: r.name,
    registerAddress: r.address
}));

return [messages];

const flowKey = 'alarm_state_reads';
let collected = flow.get(flowKey) || {};
const expectedCount = 9;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data) || data.length < 1) {
    node.status({ fill: "red", shape: "dot", text: "Read failed: " + msg.readName });
    return null;
}

const value = data[0] || 0;

// Store by register address for clarity
switch(msg.readName) {
    case 'runState':
        collected.runStateRaw = value;
        break;
    case 'commBoard':
        collected.commBoardFaultRaw = value;
        break;
    case 'warning1':
        collected.warningWord1Raw = value;
        break;
    case 'warning2':
        collected.warningWord2Raw = value;
        break;
    case 'fault1':
        collected.faultWord1Raw = value;
        break;
    case 'fault2':
        collected.faultWord2Raw = value;
        break;
    case 'fault3':
        collected.faultWord3Raw = value;
        break;
    case 'fault4':
        collected.faultWord4Raw = value;
        break;
    case 'workFlag':
        collected.workFlagTripData = value;
        break;
}

flow.set(flowKey, collected);

const collectedCount = Object.keys(collected).length;
node.status({ fill: "blue", shape: "dot", text: `Collected ${collectedCount}/${expectedCount}` });

if (collectedCount >= expectedCount) {
    flow.set(flowKey, null);
    msg.collectedData = collected;
    msg.payload = collected;
    return msg;
}

return null;

const data = msg.collectedData;

if (!data) {
    node.status({ fill: "red", shape: "dot", text: "No data" });
    return null;
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "Unknown";
const now = new Date().toISOString();

const activeAlarms = [];

// Helper function to add alarm
function addAlarm(code, vendorCode, severity, category) {
    if (vendorCode > 0) {
        activeAlarms.push({
            code: code,
            vendorCode: vendorCode,
            severity: severity,
            sourceDevice: "inverter",
            category: category,
            messageKey: `${category}_${code}`,
            messageParams: null,
            firstOccurredUtc: now,
            lastOccurredUtc: now,
            occurrenceCount: 1
        });
    }
}

// Check warnings (653-654)
addAlarm(653, data.warningWord1Raw, "WARNING", "warning");
addAlarm(654, data.warningWord2Raw, "WARNING", "warning");

// Check faults (655-658)
addAlarm(655, data.faultWord1Raw, "ERROR", "fault");
addAlarm(656, data.faultWord2Raw, "ERROR", "fault");
addAlarm(657, data.faultWord3Raw, "ERROR", "fault");
addAlarm(658, data.faultWord4Raw, "ERROR", "fault");

// Check comm board fault (648)
addAlarm(648, data.commBoardFaultRaw, "ALARM", "comm_fault");

const state = {
    kind: "InverterAlarmState",
    timestampUtc: now,
    version: 1,
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,

    runStateRaw: data.runStateRaw,
    commBoardFaultRaw: data.commBoardFaultRaw,

    warningWord1Raw: data.warningWord1Raw,
    warningWord2Raw: data.warningWord2Raw,

    faultWord1Raw: data.faultWord1Raw,
    faultWord2Raw: data.faultWord2Raw,
    faultWord3Raw: data.faultWord3Raw,
    faultWord4Raw: data.faultWord4Raw,

    workFlagTripData: data.workFlagTripData,

    activeAlarms: activeAlarms
};

msg.payload = state;
msg.state = state;
msg.hasAlarms = activeAlarms.length > 0;

node.status({ 
    fill: activeAlarms.length > 0 ? "red" : "green", 
    shape: "dot", 
    text: `${activeAlarms.length} alarm(s)` 
});

return msg;

// Only send to ThingsBoard if there are active alarms
if (msg.hasAlarms) {
    node.status({ fill: "red", shape: "dot", text: "Sending alarms" });
    return msg;
}

node.status({ fill: "green", shape: "dot", text: "No alarms - skipped" });
return null;
